// SelectByHash implements mm_repository.PasswordResetToken
func (mmSelectByHash *PasswordResetTokenMock) SelectByHash(ctx context.Context, tokenHash string) (p1 domain.PasswordResetToken, err error) {
	mm_atomic.AddUint64(&mmSelectByHash.beforeSelectByHashCounter, 1)
	defer mm_atomic.AddUint64(&mmSelectByHash.afterSelectByHashCounter, 1)

	mmSelectByHash.t.Helper()

	if mmSelectByHash.inspectFuncSelectByHash != nil {
		mmSelectByHash.inspectFuncSelectByHash(ctx, tokenHash)
	}

	mm_params := PasswordResetTokenMockSelectByHashParams{ctx, tokenHash}

	// Record call args
	mmSelectByHash.SelectByHashMock.mutex.Lock()
	mmSelectByHash.SelectByHashMock.callArgs = append(mmSelectByHash.SelectByHashMock.callArgs, &mm_params)
	mmSelectByHash.SelectByHashMock.mutex.Unlock()

	for _, e := range mmSelectByHash.SelectByHashMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.p1, e.results.err
		}
	}

	if mmSelectByHash.SelectByHashMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmSelectByHash.SelectByHashMock.defaultExpectation.Counter, 1)
		mm_want := mmSelectByHash.SelectByHashMock.defaultExpectation.params
		mm_want_ptrs := mmSelectByHash.SelectByHashMock.defaultExpectation.paramPtrs

		mm_got := PasswordResetTokenMockSelectByHashParams{ctx, tokenHash}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmSelectByHash.t.Errorf("PasswordResetTokenMock.SelectByHash got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSelectByHash.SelectByHashMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.tokenHash != nil && !minimock.Equal(*mm_want_ptrs.tokenHash, mm_got.tokenHash) {
				mmSelectByHash.t.Errorf("PasswordResetTokenMock.SelectByHash got unexpected parameter tokenHash, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSelectByHash.SelectByHashMock.defaultExpectation.expectationOrigins.originTokenHash, *mm_want_ptrs.tokenHash, mm_got.tokenHash, minimock.Diff(*mm_want_ptrs.tokenHash, mm_got.tokenHash))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmSelectByHash.t.Errorf("PasswordResetTokenMock.SelectByHash got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmSelectByHash.SelectByHashMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmSelectByHash.SelectByHashMock.defaultExpectation.results
		if mm_results == nil {
			mmSelectByHash.t.Fatal("No results are set for the PasswordResetTokenMock.SelectByHash")
		}
		return (*mm_results).p1, (*mm_results).err
	}
	if mmSelectByHash.funcSelectByHash != nil {
		return mmSelectByHash.funcSelectByHash(ctx, tokenHash)
	}
	mmSelectByHash.t.Fatalf("Unexpected call to PasswordResetTokenMock.SelectByHash. %v %v", ctx, tokenHash)
	return
}

